private List<BaselineRow> scanDeployValues(Path deployRoot) throws IOException {
    List<BaselineRow> rows = new ArrayList<>();
    try (Stream<Path> stream = Files.walk(deployRoot)) {
        for (Path file : stream.filter(f -> f.toString().endsWith("values.yaml"))
                .collect(Collectors.toList())) {
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            String xmx = null;
            String memory = null;
            for (String line : lines) {
                Matcher xmxMatcher = XMX_PATTERN.matcher(line);      // -Xmx(\\d+)([mMgG])
                if (xmxMatcher.find()) {
                    xmx = xmxMatcher.group(1) + xmxMatcher.group(2);
                }
                Matcher memMatcher = LIMIT_PATTERN.matcher(line);    // memory: (\\d+)Mi
                if (memMatcher.find()) {
                    memory = memMatcher.group(1) + "Mi";
                }
            }
            rows.add(new BaselineRow(serviceOf(file), xmx, memory,
                    heapRatio(xmx, memory)));
        }
    }
    return rows;
}

private void checkConfigClasses(Path codeRoot, List<String> warnList) throws IOException {
    try (Stream<Path> stream = Files.walk(codeRoot)) {
        for (Path file : stream.filter(f -> f.getFileName().toString().endsWith(".java"))
                .collect(Collectors.toList())) {
            String src = Files.readString(file, StandardCharsets.UTF_8);
            if (!src.contains("@Configuration")) {
                continue;
            }
            // 手写的 RedisTemplate/RabbitMQ 连接工厂会顶掉 starter 自动配置
            for (String bean : OVERRIDING_BEANS) {
                if (src.contains("@Bean") && src.contains(bean)) {
                    warnList.add(file.getFileName() + " 手写 " + bean
                            + "，properties 里的同名配置可能不生效");
                }
            }
        }
    }
}
